#include <iostream>
#include <string>
#include <string_view>

class GradeBook {
public:
    explicit GradeBook(std::string_view name) {
        setCourseName(name);
    }

    void setCourseName(std::string_view name) {
        if (name.length() <= 25) {
            courseName = name;
        } else {
            courseName = name.substr(0, 25);
            std::cout << "Name \"" << name 
                      << "\" exceeds maximum length (25).\nLimiting courseName to: "
                      << courseName << "\n";
        }
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" << getCourseName() << "!\n\n";
    }

    void determineClassAverage() const {
        int total = 0;
        int gradeCounter = 1;
        constexpr int totalStudents = 10;

        // Counter-controlled repetition: exactly 10 iterations
        while (gradeCounter <= totalStudents) {
            int grade = 0;
            if (std::cin >> grade) {
                total += grade;
                gradeCounter++;
            } else {
                break;
            }
        }

        int average = total / totalStudents;
        std::cout << "Total of all 10 grades is " << total << "\n";
        std::cout << "Class average is " << average << "\n";
    }

private:
    std::string courseName;
};

int main() {
    GradeBook myGradeBook("CS101 Intro to C++ Programming");
    myGradeBook.displayMessage();
    myGradeBook.determineClassAverage();
    return 0;
}
